// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { Ownable2StepUpgradeable } from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {
    SafeERC20Upgradeable,
    IERC20Upgradeable
} from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";

import { IFlashLoanReceiver } from "../Interfaces/IFlashLoanReceiver.sol";
import { SwapHelper } from "../SwapHelper/SwapHelper.sol";
import { IVToken } from "../Interfaces/IVToken.sol";
import { IComptroller } from "../Interfaces/IComptroller.sol";

import { ILeverageStrategiesManager } from "./ILeverageStrategiesManager.sol";

/**
 * @title LeverageStrategiesManager
 * @author Venus Protocol
 * @notice Contract for managing leveraged positions using flash loans and token swaps
 */
contract LeverageStrategiesManager is
    Ownable2StepUpgradeable,
    ReentrancyGuardUpgradeable,
    IFlashLoanReceiver,
    ILeverageStrategiesManager
{
    using SafeERC20Upgradeable for IERC20Upgradeable;

    /// @dev Success return value for VToken operations (mint, borrow, repay, redeem)
    uint256 private constant SUCCESS = 0;

    /// @dev Mantissa for fixed-point arithmetic (1e18 = 100%)
    uint256 private constant MANTISSA_ONE = 1e18;

    /// @notice The Venus comptroller contract for market interactions and flash loans execution
    IComptroller public immutable COMPTROLLER;

    /// @notice The swap helper contract for executing token swaps during leverage operations
    SwapHelper public immutable swapHelper;

    /// @notice The vBNB market address (not supported for leverage operations)
    IVToken public immutable vBNB;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Tracks operation type during flash loan callback.
    OperationType transient operationType;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores msg.sender for flash loan callback context.
    address transient operationInitiator;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores collateral market for flash loan callback.
    IVToken transient collateralMarket;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores collateral seed (enter) or redeem amount (exit).
    uint256 transient collateralAmount;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores borrowed amount seed for enterLeverageFromBorrow.
    uint256 transient borrowedAmountSeed;

    /// @dev Transient (EIP-1153): Cleared at transaction end. Stores minimum expected output after swap.
    uint256 transient minAmountOutAfterSwap;

    /**
     * @notice Contract constructor
     * @dev Sets immutable variables and disables initializers for the implementation contract
     * @param _comptroller The Venus comptroller contract address
     * @param _swapHelper The swap helper contract address
     * @param _vBNB The vBNB market address (not supported for leverage operations)
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(IComptroller _comptroller, SwapHelper _swapHelper, IVToken _vBNB) {
        if (address(_comptroller) == address(0) || address(_swapHelper) == address(0) || address(_vBNB) == address(0)) {
            revert ZeroAddress();
        }

        COMPTROLLER = _comptroller;
        swapHelper = _swapHelper;
        vBNB = _vBNB;
        _disableInitializers();
    }

    /**
     * @notice Initializes the contract
     * @dev Sets up the Ownable2Step functionality. Can only be called once.
     */
    function initialize() external initializer {
        __Ownable2Step_init();
        __ReentrancyGuard_init();
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterSingleAssetLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountSeed,
        uint256 _collateralAmountToFlashLoan
    ) external {
        if (_collateralAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        _checkMarketSupported(_collateralMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_collateralMarket, msg.sender, _collateralAmountSeed);

        operationInitiator = msg.sender;
        operationType = OperationType.ENTER_SINGLE_ASSET;
        collateralAmount = _collateralAmountSeed;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _collateralMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _collateralAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            ""
        );

        _checkAccountSafe(msg.sender);

        emit SingleAssetLeverageEntered(
            msg.sender,
            _collateralMarket,
            _collateralAmountSeed,
            _collateralAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountSeed,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);
        _accrueInterest(_borrowedMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_collateralMarket, msg.sender, _collateralAmountSeed);

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        collateralAmount = _collateralAmountSeed;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.ENTER_COLLATERAL;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageEntered(
            msg.sender,
            _collateralMarket,
            _collateralAmountSeed,
            _borrowedMarket,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function enterLeverageFromBorrow(
        IVToken _collateralMarket,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountSeed,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        _accrueInterest(_collateralMarket);
        _accrueInterest(_borrowedMarket);

        _validateAndEnterMarket(msg.sender, _collateralMarket);
        _checkAccountSafe(msg.sender);

        _transferSeedAmountFromUser(_borrowedMarket, msg.sender, _borrowedAmountSeed);

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        borrowedAmountSeed = _borrowedAmountSeed;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.ENTER_BORROW;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageEnteredFromBorrow(
            msg.sender,
            _collateralMarket,
            _borrowedMarket,
            _borrowedAmountSeed,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function exitLeverage(
        IVToken _collateralMarket,
        uint256 _collateralAmountToRedeemForSwap,
        IVToken _borrowedMarket,
        uint256 _borrowedAmountToFlashLoan,
        uint256 _minAmountOutAfterSwap,
        bytes calldata _swapData
    ) external {
        if (_borrowedAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        if (_collateralMarket == _borrowedMarket) revert IdenticalMarkets();
        _checkMarketSupported(_collateralMarket);
        _checkMarketSupported(_borrowedMarket);

        _checkUserDelegated();

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        collateralAmount = _collateralAmountToRedeemForSwap;
        minAmountOutAfterSwap = _minAmountOutAfterSwap;
        operationType = OperationType.EXIT_COLLATERAL;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _borrowedMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _borrowedAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            _swapData
        );

        _checkAccountSafe(msg.sender);

        emit LeverageExited(
            msg.sender,
            _collateralMarket,
            _collateralAmountToRedeemForSwap,
            _borrowedMarket,
            _borrowedAmountToFlashLoan
        );

        _transferDustToInitiator(_collateralMarket);
        _transferDustToInitiator(_borrowedMarket);
    }

    /// @inheritdoc ILeverageStrategiesManager
    function exitSingleAssetLeverage(IVToken _collateralMarket, uint256 _collateralAmountToFlashLoan) external {
        if (_collateralAmountToFlashLoan == 0) revert ZeroFlashLoanAmount();
        _checkMarketSupported(_collateralMarket);
        _checkUserDelegated();

        operationInitiator = msg.sender;
        collateralMarket = _collateralMarket;
        operationType = OperationType.EXIT_SINGLE_ASSET;

        IVToken[] memory borrowedMarkets = new IVToken[](1);
        borrowedMarkets[0] = _collateralMarket;
        uint256[] memory flashLoanAmounts = new uint256[](1);
        flashLoanAmounts[0] = _collateralAmountToFlashLoan;

        COMPTROLLER.executeFlashLoan(
            payable(msg.sender),
            payable(address(this)),
            borrowedMarkets,
            flashLoanAmounts,
            ""
        );

        _checkAccountSafe(msg.sender);

        emit SingleAssetLeverageExited(msg.sender, _collateralMarket, _collateralAmountToFlashLoan);

        _transferDustToInitiator(_collateralMarket);
    }

    /**
     * @notice Flash loan callback entrypoint called by Comptroller
     * @dev Protected by nonReentrant modifier to prevent reentrancy attacks during flash loan execution
     * @param vTokens Array with the borrowed vToken market (single element)
     * @param amounts Array with the borrowed underlying amount (single element)
     * @param premiums Array with the flash loan fee amount (single element)
     * @param initiator The address that initiated the flash loan (must be this contract)
     * @param onBehalf The user for whom debt will be opened
     * @param param Encoded auxiliary data for the operation (e.g., swap multicall)
     * @return success Whether the execution succeeded
     * @return repayAmounts Amounts to approve for flash loan repayment
     * @custom:error InitiatorMismatch When initiator is not this contract
     * @custom:error OnBehalfMismatch When onBehalf is not the operation initiator
     * @custom:error UnauthorizedExecutor When caller is not the Comptroller
     * @custom:error FlashLoanAssetOrAmountMismatch When array lengths mismatch or > 1 element
     * @custom:error InvalidExecuteOperation When operation type is unknown
     */
    function executeOperation(
        IVToken[] calldata vTokens,
        uint256[] calldata amounts,
        uint256[] calldata premiums,
        address initiator,
        address onBehalf,
        bytes calldata param
    ) external override nonReentrant returns (bool success, uint256[] memory repayAmounts) {
        // Only the Comptroller can invoke this callback during flash loan execution
        if (msg.sender != address(COMPTROLLER)) {
            revert UnauthorizedExecutor();
        }

        // Flash loan must be initiated by this contract to prevent unauthorized callbacks
        if (initiator != address(this)) {
            revert InitiatorMismatch();
        }

        // The flash loan beneficiary must match the user who called the entry function
        if (onBehalf != operationInitiator) {
            revert OnBehalfMismatch();
        }

        // This contract only supports single-market flash loans
        if (vTokens.length != 1 || amounts.length != 1 || premiums.length != 1) {
            revert FlashLoanAssetOrAmountMismatch();
        }

        repayAmounts = new uint256[](1);
        if (operationType == OperationType.ENTER_SINGLE_ASSET) {
            repayAmounts[0] = _handleEnterSingleAsset(onBehalf, vTokens[0], amounts[0], premiums[0]);
        } else if (operationType == OperationType.ENTER_COLLATERAL) {
            repayAmounts[0] = _handleEnterCollateral(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.ENTER_BORROW) {
            repayAmounts[0] = _handleEnterBorrow(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.EXIT_COLLATERAL) {
            repayAmounts[0] = _handleExitCollateral(onBehalf, vTokens[0], amounts[0], premiums[0], param);
        } else if (operationType == OperationType.EXIT_SINGLE_ASSET) {
            repayAmounts[0] = _handleExitSingleAsset(onBehalf, vTokens[0], amounts[0], premiums[0]);
        } else {
            revert InvalidExecuteOperation();
        }

        return (true, repayAmounts);
    }

    /**
     * @notice Executes the enter leveraged position with single collateral operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Combines flash loaned collateral with user's seed collateral
     *      2. Supplies all collateral to the Venus market on behalf of the user
     *      3. Borrows the repayment amount (fees) on behalf of the user
     *      4. Approves the collateral asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param market The vToken market for the collateral asset
     * @param flashloanedCollateralAmount The amount of collateral assets received from flash loan
     * @param collateralAmountFees The fees to be paid on the flash loaned collateral amount
     * @return flashLoanRepayAmount The total amount of collateral assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleEnterSingleAsset(
        address onBehalf,
        IVToken market,
        uint256 flashloanedCollateralAmount,
        uint256 collateralAmountFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable collateralAsset = IERC20Upgradeable(market.underlying());

        uint256 totalCollateralAmountToMint = flashloanedCollateralAmount + collateralAmount;
        collateralAsset.forceApprove(address(market), totalCollateralAmountToMint);

        uint256 err = market.mintBehalf(onBehalf, totalCollateralAmountToMint);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, market, collateralAsset, collateralAmountFees);
    }

    /**
     * @notice Executes the enter leveraged position operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Swaps flash loaned borrowed assets for collateral assets
     *      2. Supplies all collateral received from swap plus seed to the Venus market on behalf of the user
     *      3. Borrows the repayment amount on behalf of the user
     *      4. Approves the borrowed asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed
     * @param borrowedAssetAmount The amount of borrowed assets received from flash loan
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting borrowed to collateral assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function _handleEnterCollateral(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmount,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 _minAmountOutAfterSwap = minAmountOutAfterSwap;

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());
        uint256 swappedCollateralAmountOut = _performSwap(
            borrowedAsset,
            borrowedAssetAmount,
            collateralAsset,
            _minAmountOutAfterSwap,
            swapCallData
        );

        uint256 collateralAmountToMint = swappedCollateralAmountOut + collateralAmount;
        collateralAsset.forceApprove(address(_collateralMarket), collateralAmountToMint);

        uint256 err = _collateralMarket.mintBehalf(onBehalf, collateralAmountToMint);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, borrowMarket, borrowedAsset, borrowedAssetFees);
    }

    /**
     * @notice Executes the enter leveraged position with borrowed assets operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Swaps the total borrowed assets (seed + flash loan) for collateral assets
     *      2. Supplies all collateral received from swap to the Venus market on behalf of the user
     *      3. Borrows the repayment amount on behalf of the user
     *      4. Approves the borrowed asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed
     * @param borrowedAssetAmount The amount of borrowed assets received from flash loan
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting borrowed to collateral assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (fees only)
     * @custom:error MintBehalfFailed if mint behalf operation fails
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if collateral balance after swap is below minimum
     */
    function _handleEnterBorrow(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmount,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 _minAmountOutAfterSwap = minAmountOutAfterSwap;

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());

        uint256 totalBorrowedAmountToSwap = borrowedAmountSeed + borrowedAssetAmount;

        uint256 swappedCollateralAmountOut = _performSwap(
            borrowedAsset,
            totalBorrowedAmountToSwap,
            collateralAsset,
            _minAmountOutAfterSwap,
            swapCallData
        );

        collateralAsset.forceApprove(address(_collateralMarket), swappedCollateralAmountOut);

        uint256 err = _collateralMarket.mintBehalf(onBehalf, swappedCollateralAmountOut);
        if (err != SUCCESS) {
            revert MintBehalfFailed(err);
        }

        flashLoanRepayAmount = _borrowAndRepayFlashLoanFee(onBehalf, borrowMarket, borrowedAsset, borrowedAssetFees);
    }

    /**
     * @notice Executes the exit leveraged position operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Queries actual debt and caps repayment to min(flashLoanAmount, actualDebt)
     *         to handle cases where UI flash loans slightly more than current debt
     *      2. Repays user's debt (up to actual debt amount) in the borrowed market
     *      3. Calculates redeem amount accounting for treasury fee (if any)
     *      4. Redeems specified amount of collateral from the Venus market
     *      5. Swaps actual received collateral (after treasury fee) for borrowed assets
     *      6. Validates total borrowed asset balance (swap output + excess flash loan funds)
     *         is sufficient to repay flash loan, then approves repayment
     *
     * @param onBehalf Address on whose behalf the operation is performed
     * @param borrowMarket The vToken market from which assets were borrowed via flash loan
     * @param borrowedAssetAmountToRepayFromFlashLoan The amount borrowed via flash loan for debt repayment
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @param swapCallData The encoded swap instructions for converting collateral to borrowed assets
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay
     * @custom:error RepayBehalfFailed if repayment of borrowed assets fails
     * @custom:error RedeemBehalfFailed if redeem operations fail
     * @custom:error TokenSwapCallFailed if token swap execution fails
     * @custom:error SlippageExceeded if swap output is below minimum required
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleExitCollateral(
        address onBehalf,
        IVToken borrowMarket,
        uint256 borrowedAssetAmountToRepayFromFlashLoan,
        uint256 borrowedAssetFees,
        bytes calldata swapCallData
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable borrowedAsset = IERC20Upgradeable(borrowMarket.underlying());

        {
            uint256 borrowedTotalDebtAmount = borrowMarket.borrowBalanceCurrent(onBehalf);
            uint256 repayAmount = borrowedAssetAmountToRepayFromFlashLoan > borrowedTotalDebtAmount
                ? borrowedTotalDebtAmount
                : borrowedAssetAmountToRepayFromFlashLoan;

            borrowedAsset.forceApprove(address(borrowMarket), repayAmount);
            uint256 err = borrowMarket.repayBorrowBehalf(onBehalf, repayAmount);

            if (err != SUCCESS) {
                revert RepayBehalfFailed(err);
            }
        }

        // Cache transient storage reads for variables used more than once to save gas
        IVToken _collateralMarket = collateralMarket;
        uint256 collateralAmountToRedeem = collateralAmount;

        {
            uint256 treasuryPercent = COMPTROLLER.treasuryPercent();
            uint256 redeemAmount = treasuryPercent > 0
                ? (collateralAmountToRedeem * MANTISSA_ONE + (MANTISSA_ONE - treasuryPercent) - 1) /
                    (MANTISSA_ONE - treasuryPercent)
                : collateralAmountToRedeem;

            uint256 err = _collateralMarket.redeemUnderlyingBehalf(onBehalf, redeemAmount);
            if (err != SUCCESS) {
                revert RedeemBehalfFailed(err);
            }
        }

        IERC20Upgradeable collateralAsset = IERC20Upgradeable(_collateralMarket.underlying());

        _performSwap(
            collateralAsset,
            collateralAsset.balanceOf(address(this)),
            borrowedAsset,
            minAmountOutAfterSwap,
            swapCallData
        );

        flashLoanRepayAmount = borrowedAssetAmountToRepayFromFlashLoan + borrowedAssetFees;

        if (borrowedAsset.balanceOf(address(this)) < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        borrowedAsset.forceApprove(address(borrowMarket), flashLoanRepayAmount);
    }

    /**
     * @notice Executes the exit leveraged position with single collateral operation during flash loan callback
     * @dev This function performs the following steps:
     *      1. Queries actual debt and caps repayment to min(flashLoanAmount, actualDebt)
     *         to handle cases where UI flash loans slightly more than current debt
     *      2. Repays user's debt (up to actual debt amount) in the market
     *      3. Calculates redeem amount accounting for treasury fee (if any)
     *      4. Caps redeem amount to user's actual collateral balance to prevent revert
     *         when user entered with zero seed (collateral equals borrowed amount)
     *      5. Redeems collateral (up to user's balance) to repay flash loan
     *      6. Approves the collateral asset for repayment to the flash loan
     * @param onBehalf Address on whose behalf the operation is performed
     * @param market The vToken market for both collateral and borrowed assets
     * @param flashloanedCollateralAmount The amount borrowed via flash loan for debt repayment
     * @param collateralAmountFees The fees to be paid on the flash loaned collateral amount
     * @return flashLoanRepayAmount The total amount of collateral assets to repay
     * @custom:error RepayBehalfFailed if repayment of borrowed assets fails
     * @custom:error RedeemBehalfFailed if redeem operations fail
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _handleExitSingleAsset(
        address onBehalf,
        IVToken market,
        uint256 flashloanedCollateralAmount,
        uint256 collateralAmountFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        IERC20Upgradeable collateralAsset = IERC20Upgradeable(market.underlying());

        uint256 marketTotalDebtAmount = market.borrowBalanceCurrent(onBehalf);
        uint256 repayAmount = flashloanedCollateralAmount > marketTotalDebtAmount
            ? marketTotalDebtAmount
            : flashloanedCollateralAmount;

        collateralAsset.forceApprove(address(market), repayAmount);
        uint256 err = market.repayBorrowBehalf(onBehalf, repayAmount);

        if (err != SUCCESS) {
            revert RepayBehalfFailed(err);
        }

        flashLoanRepayAmount = flashloanedCollateralAmount + collateralAmountFees;

        uint256 treasuryPercent = COMPTROLLER.treasuryPercent();
        uint256 redeemAmount = treasuryPercent > 0
            ? (flashLoanRepayAmount * MANTISSA_ONE + (MANTISSA_ONE - treasuryPercent) - 1) /
                (MANTISSA_ONE - treasuryPercent)
            : flashLoanRepayAmount;

        uint256 userCollateralBalance = market.balanceOfUnderlying(onBehalf);
        if (redeemAmount > userCollateralBalance) {
            redeemAmount = userCollateralBalance;
        }

        err = market.redeemUnderlyingBehalf(onBehalf, redeemAmount);
        if (err != SUCCESS) {
            revert RedeemBehalfFailed(err);
        }

        if (collateralAsset.balanceOf(address(this)) < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        collateralAsset.forceApprove(address(market), flashLoanRepayAmount);
    }

    /**
     * @notice Performs token swap via the SwapHelper contract
     * @dev Transfers tokens to SwapHelper and executes the swap operation.
     *      The swap operation is expected to return the output tokens to this contract.
     * @param tokenIn The input token to be swapped
     * @param amountIn The amount of input tokens to swap
     * @param tokenOut The output token to receive from the swap
     * @param minAmountOut The minimum acceptable amount of output tokens
     * @param param The encoded swap instructions/calldata for the SwapHelper
     * @return amountOut The actual amount of output tokens received from the swap
     * @custom:error TokenSwapCallFailed if the swap execution fails
     * @custom:error SlippageExceeded if the swap output is below the minimum required
     */
    function _performSwap(
        IERC20Upgradeable tokenIn,
        uint256 amountIn,
        IERC20Upgradeable tokenOut,
        uint256 minAmountOut,
        bytes calldata param
    ) internal returns (uint256 amountOut) {
        tokenIn.safeTransfer(address(swapHelper), amountIn);

        uint256 tokenOutBalanceBefore = tokenOut.balanceOf(address(this));

        (bool success, ) = address(swapHelper).call(param);
        if (!success) {
            revert TokenSwapCallFailed();
        }

        uint256 tokenOutBalanceAfter = tokenOut.balanceOf(address(this));

        amountOut = tokenOutBalanceAfter - tokenOutBalanceBefore;
        if (amountOut < minAmountOut) {
            revert SlippageExceeded();
        }

        return amountOut;
    }

    /**
     * @notice Transfers tokens from the user to this contract if amount > 0
     * @dev If the specified amount is greater than zero, transfers tokens from the user.
     *      Reverts if the actual transferred amount does not match the expected amount.
     * @param market The vToken market whose underlying asset is to be transferred
     * @param user The address of the user to transfer tokens from
     * @param amount The amount of tokens to transfer
     * @custom:error TransferFromUserFailed if the transferred amount does not match the expected amount
     */
    function _transferSeedAmountFromUser(IVToken market, address user, uint256 amount) internal {
        if (amount > 0) {
            IERC20Upgradeable token = IERC20Upgradeable(market.underlying());
            token.safeTransferFrom(user, address(this), amount);
        }
    }

    /**
     * @notice Transfers any remaining dust amounts back to the operation initiator
     * @dev This function returns small remaining balances to the user who initiated the operation.
     *      Should be called after leverage operations to ensure no funds are left in the contract.
     * @param market The vToken market whose underlying asset dust should be transferred
     */
    function _transferDustToInitiator(IVToken market) internal {
        IERC20Upgradeable asset = IERC20Upgradeable(market.underlying());

        uint256 dustAmount = asset.balanceOf(address(this));
        if (dustAmount > 0) {
            // Cache transient storage read to save gas
            address _operationInitiator = operationInitiator;
            asset.safeTransfer(_operationInitiator, dustAmount);
            emit DustTransferred(_operationInitiator, address(asset), dustAmount);
        }
    }

    /**
     * @notice Borrows assets on behalf of the user to repay the flash loan fee
     * @dev Borrows the total amount needed to repay the flash loan fee
     *      and approves the borrowed asset for repayment to the flash loan.
     * @param onBehalf Address on whose behalf assets will be borrowed
     * @param borrowMarket The vToken market from which assets will be borrowed
     * @param borrowedAsset The underlying asset being borrowed
     * @param borrowedAssetFees The fees to be paid on the borrowed asset amount
     * @return flashLoanRepayAmount The total amount of borrowed assets to repay (only fees)
     * @custom:error BorrowBehalfFailed if borrow behalf operation fails
     * @custom:error InsufficientFundsToRepayFlashloan if insufficient funds are available to repay the flash loan
     */
    function _borrowAndRepayFlashLoanFee(
        address onBehalf,
        IVToken borrowMarket,
        IERC20Upgradeable borrowedAsset,
        uint256 borrowedAssetFees
    ) internal returns (uint256 flashLoanRepayAmount) {
        flashLoanRepayAmount = borrowedAssetFees;

        uint256 marketBalanceBeforeBorrow = borrowedAsset.balanceOf(address(borrowMarket));
        uint256 err = borrowMarket.borrowBehalf(onBehalf, flashLoanRepayAmount);
        if (err != SUCCESS) {
            revert BorrowBehalfFailed(err);
        }
        uint256 marketBalanceAfterBorrow = borrowedAsset.balanceOf(address(borrowMarket));

        if (marketBalanceBeforeBorrow - marketBalanceAfterBorrow < flashLoanRepayAmount) {
            revert InsufficientFundsToRepayFlashloan();
        }

        borrowedAsset.forceApprove(address(borrowMarket), flashLoanRepayAmount);
    }

    /**
     * @notice Accrues interest on a vToken market
     * @dev Must be called before safety checks to ensure borrow balances reflect accumulated interest
     * @param market The vToken market to accrue interest on
     * @custom:error AccrueInterestFailed if the accrueInterest call returns a non-zero error code
     */
    function _accrueInterest(IVToken market) internal {
        uint256 err = market.accrueInterest();
        if (err != SUCCESS) revert AccrueInterestFailed(err);
    }

    /**
     * @notice Ensures the user has entered the market before operations
     * @dev If user is not a member of market the function calls Comptroller to enter market on behalf of user
     * @param user The account for which membership is validated/updated
     * @param market The vToken market the user must enter
     * @custom:error EnterMarketFailed when Comptroller.enterMarketBehalf returns a non-zero error code
     */
    function _validateAndEnterMarket(address user, IVToken market) internal {
        if (!COMPTROLLER.checkMembership(user, market)) {
            uint256 err = COMPTROLLER.enterMarketBehalf(user, address(market));
            if (err != SUCCESS) revert EnterMarketFailed(err);
        }
    }

    /**
     * @notice Checks if the caller has delegated this contract in the Comptroller
     * @custom:error NotAnApprovedDelegate if caller has not approved this contract as delegate
     */
    function _checkUserDelegated() internal view {
        if (!COMPTROLLER.approvedDelegates(msg.sender, address(this))) {
            revert NotAnApprovedDelegate();
        }
    }

    /**
     * @notice Checks if a `user` account is safe from liquidation
     * @dev Verifies that the user's account has no liquidity shortfall and the comptroller
     *      returned no errors when calculating account liquidity. This ensures the account
     *      won't be immediately liquidatable after the leverage operation.
     * @param user The address to check account safety for
     * @custom:error OperationCausesLiquidation if the account has a liquidity shortfall or comptroller error
     */
    function _checkAccountSafe(address user) internal view {
        (uint256 err, , uint256 shortfall) = COMPTROLLER.getBorrowingPower(user);
        if (err != SUCCESS || shortfall > 0) revert OperationCausesLiquidation(err);
    }

    /**
     * @notice Ensures that the given market is supported for leverage operations
     * @dev A market must be listed in the Comptroller and must not be vBNB.
     *      vBNB is excluded because it uses native BNB which requires special handling
     *      that this contract does not support.
     * @param market The vToken address to validate
     * @custom:error MarketNotListed if the market is not listed in Comptroller
     * @custom:error VBNBNotSupported if the market is vBNB
     */
    function _checkMarketSupported(IVToken market) internal view {
        (bool isMarketListed, , ) = COMPTROLLER.markets(address(market));
        if (!isMarketListed) revert MarketNotListed(address(market));
        if (market == vBNB) revert VBNBNotSupported();
    }
}

contracts/RelativePositionManager/IPosit.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { IComptroller, IVToken } from "../Interfaces.sol";

/**
 * @title IPositionAccount
 * @author Venus Protocol
 * @notice Interface for Position Account contracts
 * @dev Minimal proxy contracts that hold user funds and execute operations on behalf of users
 *      in the Venus protocol. These contracts are deployed deterministically using clones.
 */
interface IPositionAccount {
    /**
     * @notice Initializes a new position account clone
     * @dev Can only be called once per clone. Sets the owner, long/short vTokens, and delegates to manager.
     * @param owner_ Address of the position account owner
     * @param longVToken_ Address of the long market vToken
     * @param shortVToken_ Address of the short market vToken
     */
    function initialize(address owner_, address longVToken_, address shortVToken_) external;

    /**
     * @notice Forwards enterLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Ensures the position account is msg.sender to LM.
     * @param collateralMarket Collateral (e.g. long) vToken to supply after swap
     * @param collateralAmountSeed Optional seed amount of collateral (RPM uses 0; collateral from swap)
     * @param borrowedMarket Borrowed (e.g. short) vToken to flash-borrow
     * @param borrowedAmountToFlashLoan Amount to borrow via flash loan
     * @param minAmountOutAfterSwap Minimum collateral out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. borrowed → collateral)
     */
    function enterLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountSeed,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Forwards exitLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Enables clearer flow and better revert messages.
     * @param collateralMarket Collateral (e.g. long) vToken to redeem
     * @param collateralAmountToRedeemForSwap Amount of collateral to redeem for swap
     * @param borrowedMarket Borrowed (e.g. short) vToken to repay
     * @param borrowedAmountToFlashLoan Amount to repay via flash loan
     * @param minAmountOutAfterSwap Minimum amount out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. collateral → borrowed)
     */
    function exitLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountToRedeemForSwap,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external;

    /**
     * @notice Forwards exitSingleAssetLeverage to the LeverageStrategiesManager (collateral and debt are same asset)
     * @dev Only callable by the RelativePositionManager. Use when DSA == short: repay short debt by redeeming DSA vTokens, no swap.
     * @param collateralMarket vToken market for both collateral and debt (e.g. DSA when DSA == short)
     * @param collateralAmountToFlashLoan Amount to borrow via flash loan for debt repayment
     */
    function exitSingleAssetLeverage(IVToken collateralMarket, uint256 collateralAmountToFlashLoan) external;

    /**
     * @notice Transfers full balance of an ERC20 token from this position account to its owner (dust recovery)
     * @dev Only callable by the RelativePositionManager. Used to sweep dust to the position owner.
     * @param token Address of the ERC20 token to transfer
     */
    function transferDustToOwner(address token) external;

    /**
     * @notice Exits a market by calling comptroller.exitMarket with this position account as the sender
     * @dev Only callable by the RelativePositionManager. The position account directly calls the Comptroller.
     * @param vTokenToExit Address of the vToken market to exit
     */
    function exitMarket(address vTokenToExit) external;

    /**
     * @notice Executes multiple generic calls to external contracts on behalf of the position account
     * @dev Only callable by the authorized RelativePositionManager contract.
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     */
    function genericCalls(address[] calldata targets, bytes[] calldata data) external;

    /**
     * @notice Gets the Comptroller contract
     * @return Address of the Venus Comptroller
     */
    function COMPTROLLER() external view returns (IComptroller);

    /**
     * @notice Gets the authorized RelativePositionManager contract
     * @return Address of the RelativePositionManager contract
     */
    function RELATIVE_POSITION_MANAGER() external view returns (address);

    /**
     * @notice Gets the LeverageStrategiesManager contract
     * @return Address of the LeverageStrategiesManager contract
     */
    function LEVERAGE_MANAGER() external view returns (address);

    /**
     * @notice Gets the owner of this position account
     * @return owner Address of the position account owner
     */
    function owner() external view returns (address owner);

    /**
     * @notice Gets the long vToken for this position
     * @return longVToken Address of the long market vToken
     */
    function longVToken() external view returns (address longVToken);

    /**
     * @notice Gets the short vToken for this position
     * @return shortVToken Address of the short market vToken
     */
    function shortVToken() external view returns (address shortVToken);
}

contracts/RelativePositionManager/IRelat.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { IVToken } from "../Interfaces.sol";

/**
 * @title IRelativePositionManager
 * @author Venus Protocol
 * @notice Interface for the Relative Position Manager contract
 * @dev This contract manages isolated leveraged positions using 3-token logic (DSA + Long + Short)
 *      where positions are opened on behalf of PositionAccount contracts deployed per user per position pair.
 */
interface IRelativePositionManager {
    /// @notice Structure representing a user's position
    struct Position {
        address user; // User who owns this position (immutable)
        address longVToken; // Long vToken market (immutable)
        address shortVToken; // Short vToken market (immutable)
        address positionAccount; // Address of the PositionAccount contract (immutable)
        bool isActive; // Whether position is currently active (mutable)
        uint8 dsaIndex; // Index of DSA in dsaVTokens array sets on activation (mutable)
        address dsaVToken; // DSA vToken market address sets on activation (mutable)
        uint256 suppliedPrincipalVTokens; // Total DSA supplied as collateral, in vToken amount (mutable)
        uint256 effectiveLeverage; // Leverage ratio sets on activation (mutable)
        uint256 cycleId; // Current cycle ID, increments on each activation (mutable)
    }

    /// @notice Structure for utilization calculation results
    struct UtilizationInfo {
        uint256 actualCapitalUtilized; // Capital used based on collateral LTV ratios (in USD)
        uint256 nominalCapitalUtilized; // Capital used based on leverage ratio (in USD)
        uint256 finalCapitalUtilized; // Position capital capped by supplied principal (in USD)
        uint256 availableCapitalUSD; // Remaining capital available for borrowing (in USD)
        uint256 withdrawableAmount; // Amount that can be withdrawn in DSA token terms
        uint256 clampedLeverage; // min(storedEffectiveLeverage, currentMaxLeverage) at time of computation
    }

    /// @notice Swap parameters for closeWithProfitAndDeactivate
    struct CloseWithProfitParams {
        uint256 longAmountToRedeemForRepay;
        uint256 minAmountOutRepay;
        bytes swapDataRepay;
        uint256 longAmountToRedeemForProfit;
        uint256 minAmountOutProfit;
        bytes swapDataProfit;
    }

    /// @notice Swap parameters for closeWithLossAndDeactivate
    struct CloseWithLossParams {
        uint256 longAmountToRedeemForFirstSwap;
        uint256 shortAmountToRepayForFirstSwap;
        uint256 minAmountOutFirst;
        bytes swapDataFirst;
        uint256 dsaAmountToRedeemForSecondSwap;
        uint256 minAmountOutSecond;
        bytes swapDataSecond;
    }

    /// @dev USD values for long collateral, short debt, and supplied principal (and prices used for conversions)
    struct PositionValuesUSD {
        uint256 longValueUSD;
        uint256 borrowValueUSD;
        uint256 suppliedPrincipalUSD;
        uint256 dsaPrice;
        uint256 shortPrice;
    }

    /// @custom:error PositionAlreadyExists when user tries to activate an already active position
    error PositionAlreadyExists();

    /// @custom:error PositionNotActive when trying to operate on inactive position
    error PositionNotActive();

    /// @custom:error PositionNotFullyClosed when trying to deactivate a position that still has short debt
    error PositionNotFullyClosed();

    /// @custom:error PartiallyPaused when a risk action is called while partially paused
    error PartiallyPaused();

    /// @custom:error CompletelyPaused when any state-changing function is called while completely paused
    error CompletelyPaused();

    /// @custom:error InvalidDSA when DSA index or address is not valid
    error InvalidDSA();

    /// @custom:error DSAInactive when a DSA vToken is configured but not active for new activations
    error DSAInactive();

    /// @custom:error SameDSAActiveStatus when setDSAVTokenActive is called with the current active flag
    error SameDSAActiveStatus();

    /// @custom:error DSAVTokenAlreadyAdded when trying to add an already configured DSA vToken
    error DSAVTokenAlreadyAdded();

    /// @custom:error InsufficientPrincipal when supplied principal is insufficient
    error InsufficientPrincipal();

    /// @custom:error InvalidLeverage when leverage is invalid (0 or too low or exceeds max)
    error InvalidLeverage();

    /// @custom:error BorrowAmountExceedsMaximum when borrow amount exceeds the calculated maximum based on capital utilization
    error BorrowAmountExceedsMaximum();

    /// @custom:error InsufficientWithdrawableAmount when trying to withdraw more than allowed
    error InsufficientWithdrawableAmount();

    /// @custom:error ZeroAddress when a zero address is provided
    error ZeroAddress();

    /// @custom:error InvalidOraclePrice when oracle returns zero or invalid price
    error InvalidOraclePrice();

    /// @custom:error AssetNotListed when asset market is not listed in comptroller
    error AssetNotListed();

    /// @custom:error VBNBNotSupported when trying to use vBNB market
    error VBNBNotSupported();

    /// @custom:error MintBehalfFailed when minting vTokens on behalf fails
    /// @param errorCode Error code returned by the vToken mintBehalf call
    error MintBehalfFailed(uint256 errorCode);

    /// @custom:error ZeroVTokensMinted when supplied amount rounds down to 0 vTokens due to exchange rate
    /// (e.g., supplying 1 wei when vToken exchange rate > 1e18). Ensure amount is large enough to mint at least 1 vToken.
    error ZeroVTokensMinted();

    /// @custom:error EnterMarketFailed when entering market on behalf fails
    error EnterMarketFailed(uint256 errorCode);

    /// @custom:error ZeroAmount when amount is zero
    error ZeroAmount();

    /// @custom:error ZeroShortAmount when borrow amount is zero
    error ZeroShortAmount();

    /// @custom:error ZeroDebt when there is no short debt to close
    error ZeroDebt();

    /// @custom:error SameMarketNotAllowed when long and short markets are identical
    error SameMarketNotAllowed();

    /// @custom:error MinAmountOutSecondBelowDebt when minAmountOutSecond is less than remaining short debt (second swap)
    error MinAmountOutSecondBelowDebt();

    /// @custom:error MinAmountOutRepayBelowDebt when minAmountOutRepay is less than current short debt
    error MinAmountOutRepayBelowDebt();

    /// @custom:error RedeemBehalfFailed when redeeming vTokens on behalf fails
    /// @param errorCode Error code returned by the vToken redeemUnderlyingBehalf call
    error RedeemBehalfFailed(uint256 errorCode);

    /// @custom:error TokenSwapCallFailed when swap execution via SwapHelper fails
    error TokenSwapCallFailed();

    /// @custom:error SlippageExceeded when swap output is below the minimum required
    error SlippageExceeded();

    /// @custom:error PositionAccountImplementationNotSet when trying to deploy or compute position accounts before implementation is configured
    error PositionAccountImplementationNotSet();

    /// @custom:error PositionAccountImplementationLocked when PositionAccountImplementation is already locked and cannot be changed
    error PositionAccountImplementationLocked();

    /// @custom:error SameProportionalCloseTolerance when setter is called with the current tolerance value
    error SameProportionalCloseTolerance();

    /// @custom:error InvalidProportionalCloseTolerance when tolerance is outside [1, 10000]
    error InvalidProportionalCloseTolerance();

    /// @custom:error ProportionalCloseAmountOutOfTolerance when user-provided close amounts are not within 1% of BPS-derived expected amounts
    error ProportionalCloseAmountOutOfTolerance();

    /// @custom:error InvalidCollateralFactor when a market's collateral factor is configured to be >= 100%
    error InvalidCollateralFactor();

    /// @custom:error InvalidLongAmountToRedeem when proportional close expects zero long (no long to close) but user passed non-zero total long amount
    error InvalidLongAmountToRedeem();

    /// @custom:error InvalidCloseFractionBps when closeFractionBps is not between 1 and 10000 (basis points)
    error InvalidCloseFractionBps();

    /// @custom:error ExcessiveShortDust when short token dust on position account after closeWithLoss exit legs exceeds proportional tolerance of total repaid
    error ExcessiveShortDust();

    /// @notice Emitted when a user activates a position account
    /// @param user Address of the user
    /// @param longAsset Address of the long asset
    /// @param shortAsset Address of the short asset
    /// @param dsaAsset Address of the DSA asset
    /// @param positionAccount Address of the deployed PositionAccount
    /// @param cycleId Current cycle ID of the position (increments on each activation)
    /// @param initialPrincipal Initial principal supplied during activation (required, > 0)
    /// @param effectiveLeverage Target leverage ratio for the position
    event PositionActivated(
        address indexed user,
        address indexed longAsset,
        address indexed shortAsset,
        address dsaAsset,
        address positionAccount,
        uint256 cycleId,
        uint256 initialPrincipal,
        uint256 effectiveLeverage
    );

    /// @notice Emitted when a user supplies additional principal
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param dsaAsset Address of the DSA asset
    /// @param amount Amount supplied
    /// @param newTotalPrincipal New total principal amount
    event PrincipalSupplied(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address dsaAsset,
        uint256 amount,
        uint256 newTotalPrincipal
    );

    /// @notice Emitted when a position is opened (during activateAndOpenPosition flow)
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param longAsset Address of the long asset
    /// @param shortAsset Address of the short asset
    /// @param dsaAsset Address of the DSA asset
    /// @param shortAmount Amount borrowed in short asset
    /// @param initialPrincipal Initial principal supplied during activation (required, > 0)
    event PositionOpened(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address longAsset,
        address shortAsset,
        address dsaAsset,
        uint256 shortAmount,
        uint256 initialPrincipal
    );

    /// @notice Emitted when an existing position is scaled (additional borrow-long added to existing position)
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param longAsset Address of the long asset
    /// @param shortAsset Address of the short asset
    /// @param dsaAsset Address of the DSA asset
    /// @param shortAmount Amount borrowed in short asset
    /// @param additionalPrincipal Additional principal supplied this call (0 if none)
    event PositionScaled(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address longAsset,
        address shortAsset,
        address dsaAsset,
        uint256 shortAmount,
        uint256 additionalPrincipal
    );

    /// @notice Emitted when a position is closed (partially or fully)
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param closeFractionBps Proportion closed in basis points (10000 = 100%, 1 = 0.01% minimum)
    /// @param amountRepaid Short debt repaid in this close
    /// @param amountRedeemed Long collateral redeemed in this close
    /// @param amountRedeemedDsa DSA amount redeemed in this close (loss close second leg; 0 for profit close)
    /// @param longDustRedeemed Remaining long collateral redeemed and transferred to user on 100% close (0 for partial close).
    ///         When DSA == Long, this represents an internal reclassification rather than a completed transfer;
    ///         if deactivate is called, the corresponding funds will be paid out as part of dsaRedeemed in the PositionDeactivated event.
    event PositionClosed(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        uint256 closeFractionBps,
        uint256 amountRepaid,
        uint256 amountRedeemed,
        uint256 amountRedeemedDsa,
        uint256 longDustRedeemed
    );

    /// @notice Emitted when long is converted to profit (DSA) during closeWithProfit
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param amountConvertedToProfit Long amount redeemed and swapped to DSA as profit (underlying terms)
    /// @param newTotalPrincipal New total principal amount in vTokens after conversion
    event ProfitConverted(
        address indexed user,
        address indexed positionAccount,
        uint256 amountConvertedToProfit,
        uint256 newTotalPrincipal
    );

    /// @notice Emitted when principal is withdrawn
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param dsaAsset Address of the DSA asset
    /// @param amount Amount withdrawn
    /// @param remainingPrincipal Remaining principal after withdrawal
    event PrincipalWithdrawn(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        address dsaAsset,
        uint256 amount,
        uint256 remainingPrincipal
    );

    /// @notice Emitted when a position is deactivated
    /// @param user Address of the user
    /// @param positionAccount Address of the position account
    /// @param cycleId The cycle ID of the position
    /// @param longRedeemed Amount of long underlying redeemed to user (0 when DSA == long)
    /// @param dsaRedeemed Amount of DSA underlying redeemed to user
    event PositionDeactivated(
        address indexed user,
        address indexed positionAccount,
        uint256 cycleId,
        uint256 longRedeemed,
        uint256 dsaRedeemed
    );

    /// @notice Emitted when underlying tokens are transferred from this contract to a user
    /// @param token Address of the underlying ERC20 token
    /// @param from Account on whose behalf the underlying was redeemed
    /// @param to Recipient address (typically msg.sender)
    /// @param amount Amount of underlying transferred
    event UnderlyingTransferred(address indexed token, address indexed from, address indexed to, uint256 amount);

    /// @notice Emitted when supplied principal is refreshed down to match actual vToken balance (e.g. after liquidation seized vTokens)
    /// @param user Position owner
    /// @param positionAccount Position account whose principal was refreshed
    /// @param oldSuppliedPrincipal Previous suppliedPrincipal (vToken amount)
    /// @param newSuppliedPrincipal New suppliedPrincipal (capped at actual vToken balance)
    event RefreshedSuppliedPrincipal(
        address indexed user,
        address indexed positionAccount,
        uint256 oldSuppliedPrincipal,
        uint256 newSuppliedPrincipal
    );

    /// @notice Emitted when partial pause state is toggled
    /// @param paused New partial pause state
    event PartialPauseToggled(bool paused);

    /// @notice Emitted when complete pause state is toggled
    /// @param paused New complete pause state
    event CompletePauseToggled(bool paused);

    /// @notice Emitted when a new DSA vToken is added
    /// @param dsaVToken Address of the DSA vToken added
    /// @param index Index of the DSA vToken in the array
    event DSAVTokenAdded(address indexed dsaVToken, uint8 index);

    /// @notice Emitted when the active flag for a DSA vToken is updated
    /// @param dsaVToken Address of the DSA vToken
    /// @param index Index of the DSA vToken in the internal mapping
    /// @param active New active flag (true to allow new activations, false to block them)
    event DSAVTokenActiveUpdated(address indexed dsaVToken, uint8 index, bool active);

    /// @notice Emitted when the PositionAccount implementation address is set (can only be set once)
    /// @param implementation PositionAccount implementation address
    event PositionAccountImplementationSet(address indexed implementation);

    /// @notice Emitted when the proportional close tolerance is updated
    /// @param oldTolerance Previous tolerance value (in basis points)
    /// @param newTolerance New tolerance value (in basis points)
    event ProportionalCloseToleranceUpdated(uint256 indexed oldTolerance, uint256 indexed newTolerance);

    /// @notice Emitted when a new PositionAccount clone is deployed for a user and asset pair
    /// @param user Owner of the position account
    /// @param longAsset Long asset vToken address
    /// @param shortAsset Short asset vToken address
    /// @param positionAccount Address of the deployed PositionAccount clone
    event PositionAccountDeployed(
        address indexed user,
        address indexed longAsset,
        address indexed shortAsset,
        address positionAccount
    );

    /**
     * @notice Returns the number of configured DSA vTokens (also the next index to assign)
     * @return count Current value of the DSA vToken index counter
     */
    function dsaVTokenIndexCounter() external view returns (uint8 count);

    /**
     * @notice Activates a position and opens it with initial leverage (combined in one transaction)
     * @dev Deploys a new PositionAccount contract if one doesn't exist for this user/asset combination.
     *      Sets up the position with initial principal, then immediately opens/borrows with shortAmount.
     *      Emits both PositionActivated and PositionOpened events.
     * @param longVToken The vToken market address for the asset to long
     * @param shortVToken The vToken market address for the asset to short
     * @param dsaIndex Index of the DSA vToken in the dsaVTokens array
     * @param initialPrincipal Required initial principal amount to supply during activation (must be > 0)
     * @param effectiveLeverage The target leverage ratio for this position (in mantissa, e.g., 2e18 = 2x leverage)
     * @param shortAmount Amount to borrow in shortAsset terms
     * @param minLongAmount Minimum amount of long asset expected from swap
     * @param swapData Swap instructions for converting shortAsset to longAsset
     */
    function activateAndOpenPosition(
        address longVToken,
        address shortVToken,
        uint8 dsaIndex,
        uint256 initialPrincipal,
        uint256 effectiveLeverage,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) external;

    /**
     * @notice Supplies additional principal to an active position
     * @dev Can be called multiple times to increase collateral. DSA is taken from the position (set on activation).
     * @param longVToken The vToken market address for the long asset
     * @param shortVToken The vToken market address for the short asset
     * @param amount Amount of DSA underlying to supply
     */
    function supplyPrincipal(address longVToken, address shortVToken, uint256 amount) external;

    /**
     * @notice Scales an existing position by adding additional leverage (borrow + swap to long)
     * @dev Can only be called on an already-active position. Optionally supply additional principal
     *      via additionalPrincipal; otherwise uses existing principal. Validates that shortAmount doesn't
     *      exceed the maximum allowed based on capital utilization. DSA is taken from the position (set during activation).
     *      Emits PositionScaled event to distinguish from initial opening.
     * @param longVToken The vToken market for the asset to long
     * @param shortVToken The vToken market for the asset to short
     * @param additionalPrincipal Additional principal to supply this call (0 if none)
     * @param shortAmount Amount to borrow in shortAsset terms (must not exceed max calculated borrow)
     * @param minLongAmount Minimum amount of long asset expected from swap (protects against slippage)
     * @param swapData Swap instructions for converting shortAsset to longAsset
     */
    function scalePosition(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 additionalPrincipal,
        uint256 shortAmount,
        uint256 minLongAmount,
        bytes calldata swapData
    ) external;

    /**
     * @notice Closes a position proportionally; can realize profit on the closed slice (partial or full)
     * @dev Repay amount is derived from BPS. Total long validated against BPS (within proportionalCloseTolerance).
     * minAmountOutRepay must be >= calculated repay.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in basis points (10000 = 100%, 1 = 0.01% minimum)
     * @param longAmountToRedeemForRepay Amount of long to redeem for the repay leg (validated against BPS)
     * @param minAmountOutRepay Minimum short out from the repay swap (must be >= calculated repay amount for this BPS)
     * @param swapDataRepay Swap #1: long → short for debt repayment
     * @param longAmountToRedeemForProfit Amount of long to redeem and swap long→DSA as profit (can be non-zero for partial or full close)
     * @param minAmountOutProfit Minimum DSA out from the profit swap
     * @param swapDataProfit Swap #2: long → DSA for profit realization
     */
    function closeWithProfit(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForRepay,
        uint256 minAmountOutRepay,
        bytes calldata swapDataRepay,
        uint256 longAmountToRedeemForProfit,
        uint256 minAmountOutProfit,
        bytes calldata swapDataProfit
    ) external;

    /**
     * @notice Closes a position with loss proportionally
     * @dev closeFractionBps: 10000 = 100%, 1 = 0.01% min. First-exit long is proportion-derived; short repay in [0, expectedShort].
     *      First exit long→short, second exit DSA→short for remainder. Position fully closed.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param closeFractionBps Proportion to close in basis points (10000 = 100%, 1 = 0.01% minimum)
     * @param longAmountToRedeemForFirstSwap Long to redeem for first swap (validated against BPS within proportionalCloseTolerance)
     * @param shortAmountToRepayForFirstSwap Short to repay in first exit (0 <= value <= BPS-derived expected short)
     * @param minAmountOutFirst Minimum amount out from first swap (must be >= borrowedAmountToRepayFirst when first repay > 0)
     * @param swapDataFirst Calldata for first swap (long → short)
     * @param dsaAmountToRedeemForSecondSwap DSA to redeem for second exit repay
     * @param minAmountOutSecond Minimum amount out from second swap
     * @param swapDataSecond Calldata for second swap (DSA → short)
     */
    function closeWithLoss(
        IVToken longVToken,
        IVToken shortVToken,
        uint256 closeFractionBps,
        uint256 longAmountToRedeemForFirstSwap,
        uint256 shortAmountToRepayForFirstSwap,
        uint256 minAmountOutFirst,
        bytes calldata swapDataFirst,
        uint256 dsaAmountToRedeemForSecondSwap,
        uint256 minAmountOutSecond,
        bytes calldata swapDataSecond
    ) external;

    /**
     * @notice Fully closes a profitable position and deactivates it in a single atomic transaction.
     * @dev Hardcodes closeFractionBps to 100%. See closeWithProfit and deactivatePosition for detailed errors and events.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param profitSwapParams CloseWithProfitParams struct containing swap parameters
     */
    function closeWithProfitAndDeactivate(
        IVToken longVToken,
        IVToken shortVToken,
        CloseWithProfitParams calldata profitSwapParams
    ) external;

    /**
     * @notice Fully closes a position at a loss and deactivates it in a single atomic transaction.
     * @dev Hardcodes closeFractionBps to 100%. See closeWithLoss and deactivatePosition for detailed errors and events.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param lossSwapParams CloseWithLossParams struct containing swap parameters
     */
    function closeWithLossAndDeactivate(
        IVToken longVToken,
        IVToken shortVToken,
        CloseWithLossParams calldata lossSwapParams
    ) external;

    /**
     * @notice Deactivates a position account
     * @dev Redeems any remaining long collateral and DSA principal to the user, then deactivates.
     *      Reverts if short debt remains. User can activate with new DSA later.
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     */
    function deactivatePosition(IVToken longVToken, IVToken shortVToken) external;

    /**
     * @notice Withdraws unused principal from an active position
     * @dev Calculates utilization to determine how much can be safely withdrawn.
     *      The DSA asset is retrieved from the position data (set during activation).
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @param amount Amount to withdraw
     */
    function withdrawPrincipal(IVToken longVToken, IVToken shortVToken, uint256 amount) external;

    /**
     * @notice Adds a new DSA vToken to the supported list
     * @dev Index will be the current length of the array. Callable only by accounts with ACM permission for addDSAVToken(address).
     * @param dsaVToken The vToken market address to add as a supported DSA
     */
    function addDSAVToken(address dsaVToken) external;

    /**
     * @notice Returns the full list of configured DSA vToken markets
     * @dev Convenience helper for frontends; underlying storage is the public dsaVTokens array.
     * @return dsaVTokensList Array of DSA vToken addresses
     */
    function getDsaVTokens() external view returns (address[] memory dsaVTokensList);

    /**
     * @notice Updates the active flag for a configured DSA vToken, controlling whether it can be used for new activations
     * @dev Callable only by accounts with ACM permission for setDSAVTokenActive(uint8,bool).
     *      Does not affect already active positions, which may continue to close or withdraw principal.
     * @param dsaIndex Index of the DSA vToken in the internal mapping
     * @param active New active flag (true to allow new activations, false to block them)
     */
    function setDSAVTokenActive(uint8 dsaIndex, bool active) external;

    /**
     * @notice Returns the address at which the PositionAccount would be deployed for the given user and markets
     * @dev Same salt as used when deploying via activateAndOpenPosition (keccak256(user, longVToken, shortVToken)).
     *      Returns the address that cloneDeterministic would deploy to if called by this contract.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return predicted The predicted PositionAccount address
     */
    function getPositionAccountAddress(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (address predicted);

    /**
     * @notice Updates the implementation contract used for PositionAccount clones
     * @dev Callable only by accounts with ACM permission for setPositionAccountImplementation(address).
     *      Must be configured before any position accounts can be deployed or predicted.
     * @param positionAccountImpl Implementation contract for PositionAccount EIP-1167 clones
     */
    function setPositionAccountImplementation(address positionAccountImpl) external;

    /**
     * @notice Sets the proportional close tolerance (in basis points)
     * @dev Callable only by governance via AccessControlManager. 100 bps = 1%.
     * @param newTolerance New tolerance value in basis points
     */
    function setProportionalCloseTolerance(uint256 newTolerance) external;

    /**
     * @notice Returns the position data for a user and asset pair
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return position The Position struct
     * (user, longVToken, shortVToken, positionAccount, isActive, dsaIndex, dsaVToken, suppliedPrincipalVTokens, effectiveLeverage, cycleId)
     */
    function getPosition(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external view returns (Position memory position);

    /**
     * @notice Returns the actual long collateral balance in underlying for a given user/position,
     *         excluding DSA principal when the DSA and long assets share the same vToken market.
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return longBalance The long collateral balance in underlying units (principal excluded when shared market)
     */
    function getLongCollateralBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 longBalance);

    /**
     * @notice Returns the supplied principal balance in underlying units for a given user/position
     * @param user The position owner
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return balance The supplied principal in underlying units
     */
    function getSuppliedPrincipalBalance(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 balance);

    /**
     * @notice Executes multiple generic calls on behalf of a position account
     * @dev Callable by governance, Allows operations like emergency fund rescues.
     * @param positionAccount Address of the position account
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     */
    function executePositionAccountCall(
        address positionAccount,
        address[] calldata targets,
        bytes[] calldata data
    ) external;

    /**
     * @notice Partially pauses the manager — blocks risk-increasing operations (open, scale, withdraw, deactivate)
     *         while allowing defensive operations (close, supply principal).
     * @dev Callable only by governance via AccessControlManager.
     */
    function partialPause() external;

    /**
     * @notice Removes partial pause, re-enabling risk operations (unless completely paused).
     * @dev Callable only by governance via AccessControlManager.
     */
    function partialUnpause() external;

    /**
     * @notice Completely pauses all state-changing user operations on the manager.
     * @dev Callable only by governance via AccessControlManager. Blocks all user operations including close and supply.
     */
    function completePause() external;

    /**
     * @notice Removes complete pause, re-enabling all operations (unless partially paused).
     * @dev Callable only by governance via AccessControlManager.
     */
    function completeUnpause() external;

    /**
     * @notice Calculates capital utilization for a position
     * @dev Computes how much capital is being used vs available:
     *      1. Calculates actual capital utilized (based on collateral LTV ratios)
     *      2. Calculates nominal capital utilized (based on leverage ratio)
     *      3. Takes max (more conservative estimate)
     *      4. Caps by supplied principal
     *      5. Calculates available capital remaining
     *      6. Calculates withdrawable amount in DSA token terms
     *      Used by getAvailableShortCapacity to determine maximum borrowing capacity. DSA is read from the position.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return utilization Utilization information including available capital and withdrawable amount
     */
    function getUtilizationInfo(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (UtilizationInfo memory utilization);

    /**
     * @notice Returns the remaining short borrow capacity for a position under current market conditions
     * @dev Computes availableCapitalUSD via getUtilizationInfo (which uses live CFs), then applies:
     *      clampedLeverage = min(storedEffectiveLeverage, currentMaxLeverageAllowed)
     *      maxBorrow = (availableCapitalUSD * clampedLeverage) / shortPrice
     *      The leverage clamp ensures that any post-activation CF reduction is reflected immediately —
     *      the stored leverage is never applied beyond what current CFs permit.
     * @param user User address
     * @param longVToken The vToken market for the long asset
     * @param shortVToken The vToken market for the short asset
     * @return availableCapacity Remaining borrow capacity in short asset terms
     */
    function getAvailableShortCapacity(
        address user,
        IVToken longVToken,
        IVToken shortVToken
    ) external returns (uint256 availableCapacity);

    /**
     * @notice Returns the maximum allowed leverage for a given DSA/long market pair based on current collateral factors
     * @dev maxLeverage = CF_dsa / (1 - CF_long * (1 - proportionalCloseTolerance))
     *      Reverts with InvalidCollateralFactor if either CF >= 1 or the denominator is zero.
     * @param dsaVToken The DSA vToken market (CF_dsa used as collateral)
     * @param longVToken The long asset vToken market (CF_long used as hedge coverage)
     * @return maxLeverage The maximum leverage ratio (1e18 mantissa)
     */
    function getMaxLeverageAllowed(IVToken dsaVToken, address longVToken) external view returns (uint256 maxLeverage);
}

contracts/RelativePositionManager/Positi.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { AddressUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/AddressUpgradeable.sol";
import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { SafeERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import { IComptroller, IVToken } from "../Interfaces.sol";
import { ILeverageStrategiesManager } from "../LeverageManager/ILeverageStrategiesManager.sol";
import { IPositionAccount } from "./IPositionAccount.sol";

/**
 * @title PositionAccount
 * @author Venus Protocol
 * @notice Minimal proxy contract that holds user funds for isolated Relative Trading positions
 * @dev This contract is deployed using the clones pattern for gas efficiency.
 *      It allows the RelativePositionManager to execute calls on behalf of the user.
 *      The constructor sets immutable values shared across all clones.
 *      The initialize function sets clone-specific data.
 *
 *      DESIGN INVARIANT - External Token Transfers & Accounting Drift:
 *      Do not call mintBehalf or perform direct transfers to this contract. Use only the RelativePositionManager.
 *      External transfers to this account are not accurately tracked by the manager, causing accounting drift.
 *      No funds are lost, only accounting can drift. All operations must be routed through the RelativePositionManager
 *      to maintain accurate accounting.
 */
contract PositionAccount is Initializable, IPositionAccount {
    using AddressUpgradeable for address;
    using SafeERC20Upgradeable for IERC20Upgradeable;

    /// @notice Address of the Venus Comptroller (same for all clones)
    IComptroller public immutable COMPTROLLER;

    /// @notice Address of the authorized RelativePositionManager contract (same for all clones)
    address public immutable RELATIVE_POSITION_MANAGER;

    /// @notice Address of the LeverageStrategiesManager contract (same for all clones)
    address public immutable LEVERAGE_MANAGER;

    /// @notice Address of the position account owner (different for each clone)
    address public owner;

    /// @notice Address of the long vToken for this position
    address public longVToken;

    /// @notice Address of the short vToken for this position
    address public shortVToken;

    /**
     * @notice Emitted when a generic call is executed
     * @param target Target contract address
     * @param data Call data executed
     */
    event GenericCallExecuted(address indexed target, bytes data);

    /**
     * @notice Emitted when enterLeverage is forwarded to the LeverageManager
     * @param collateralMarket Collateral vToken market
     * @param borrowedMarket Borrowed vToken market
     * @param collateralAmountSeed Collateral seed amount (often 0)
     * @param borrowedAmount Flash loan amount
     */
    event EnterLeverageForwarded(
        address indexed collateralMarket,
        address indexed borrowedMarket,
        uint256 collateralAmountSeed,
        uint256 borrowedAmount
    );

    /**
     * @notice Emitted when exitLeverage is forwarded to the LeverageManager
     * @param collateralMarket Collateral vToken market
     * @param borrowedMarket Borrowed vToken market
     * @param collateralAmount Amount of collateral to redeem for swap
     * @param borrowedAmount Flash loan amount for repayment
     */
    event ExitLeverageForwarded(
        address indexed collateralMarket,
        address indexed borrowedMarket,
        uint256 collateralAmount,
        uint256 borrowedAmount
    );

    /**
     * @notice Emitted when exitSingleAssetLeverage is forwarded to the LeverageManager
     * @param market vToken market (collateral and debt are the same)
     * @param amount Flash loan amount for debt repayment
     */
    event ExitSingleAssetLeverageForwarded(address indexed market, uint256 amount);

    /**
     * @notice Emitted when a market is exited via the Comptroller
     * @param vToken Address of the vToken market exited
     */
    event MarketExited(address indexed vToken);

    /**
     * @notice Emitted when dust (remaining token balance) is transferred to the position owner
     * @param token Address of the ERC20 token transferred
     * @param owner Address of the position account owner receiving the dust
     * @param amount Amount of tokens transferred
     */
    event DustTransferredToOwner(address indexed token, address indexed owner, uint256 amount);

    /// @notice Thrown when caller is not the authorized RelativePositionManager
    error UnauthorizedCaller();

    /// @notice Thrown when a zero address is provided as a parameter
    error ZeroAddress();

    /// @notice Thrown when genericCalls is invoked with invalid calls length (empty or lengths mismatch)
    error InvalidCallsLength();

    /// @notice Thrown when exitMarket fails with a non-zero error code
    error ExitMarketFailed(uint256 err);

    /**
     * @notice Modifier to restrict access to only the RelativePositionManager
     */
    modifier onlyRelativePositionManager() {
        if (msg.sender != RELATIVE_POSITION_MANAGER) {
            revert UnauthorizedCaller();
        }
        _;
    }

    /**
     * @notice Constructor for the PositionAccount implementation contract
     * @dev This constructor is only called once for the implementation contract.
     *      Sets immutable values that are the same for all clones.
     * @param comptroller_ The Venus comptroller contract address
     * @param relativePositionManager_ Address of the RelativePositionManager contract
     * @param leverageManager_ Address of the LeverageStrategiesManager contract
     * @custom:error ZeroAddress if any of the addresses is zero.
     */
    constructor(IComptroller comptroller_, address relativePositionManager_, address leverageManager_) {
        if (
            address(comptroller_) == address(0) ||
            relativePositionManager_ == address(0) ||
            leverageManager_ == address(0)
        ) {
            revert ZeroAddress();
        }
        COMPTROLLER = comptroller_;
        RELATIVE_POSITION_MANAGER = relativePositionManager_;
        LEVERAGE_MANAGER = leverageManager_;

        // Prevent implementation contract from being initialized
        _disableInitializers();
    }

    /**
     * @notice Initializes a new position account clone
     * @dev Can only be called once per clone. Sets the owner, long/short vTokens, and delegates to both managers.
     * @param owner_ Address of the position account owner
     * @param longVToken_ Address of the long market vToken
     * @param shortVToken_ Address of the short market vToken
     * @custom:error ZeroAddress if any of the addresses is zero.
     */
    function initialize(address owner_, address longVToken_, address shortVToken_) external initializer {
        if (owner_ == address(0) || longVToken_ == address(0) || shortVToken_ == address(0)) {
            revert ZeroAddress();
        }

        owner = owner_;
        longVToken = longVToken_;
        shortVToken = shortVToken_;

        // Approve delegates for both managers to act on behalf of this account
        COMPTROLLER.updateDelegate(RELATIVE_POSITION_MANAGER, true);
        COMPTROLLER.updateDelegate(LEVERAGE_MANAGER, true);
    }

    /**
     * @notice Forwards enterLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Ensures the position account is msg.sender to LM,
     *      so debt/collateral and dust stay on this account. Emits EnterLeverageForwarded for debugging.
     * @param collateralMarket Collateral (e.g. long) vToken to supply after swap
     * @param collateralAmountSeed Optional seed amount of collateral (RPM uses 0)
     * @param borrowedMarket Borrowed (e.g. short) vToken to flash-borrow
     * @param borrowedAmountToFlashLoan Amount to borrow via flash loan
     * @param minAmountOutAfterSwap Minimum collateral out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. borrowed → collateral)
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     */
    function enterLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountSeed,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external onlyRelativePositionManager {
        emit EnterLeverageForwarded(
            address(collateralMarket),
            address(borrowedMarket),
            collateralAmountSeed,
            borrowedAmountToFlashLoan
        );
        ILeverageStrategiesManager(LEVERAGE_MANAGER).enterLeverage(
            collateralMarket,
            collateralAmountSeed,
            borrowedMarket,
            borrowedAmountToFlashLoan,
            minAmountOutAfterSwap,
            swapData
        );
    }

    /**
     * @notice Forwards exitLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Ensures the position account is msg.sender to LM,
     *      so debt/collateral and dust stay on this account. Emits ExitLeverageForwarded for debugging.
     * @param collateralMarket Collateral (e.g. long) vToken to redeem
     * @param collateralAmountToRedeemForSwap Amount of collateral to redeem for swap
     * @param borrowedMarket Borrowed (e.g. short) vToken to repay
     * @param borrowedAmountToFlashLoan Amount to repay via flash loan
     * @param minAmountOutAfterSwap Minimum amount out after swap (slippage protection)
     * @param swapData Swap calldata (e.g. collateral → borrowed)
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     */
    function exitLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountToRedeemForSwap,
        IVToken borrowedMarket,
        uint256 borrowedAmountToFlashLoan,
        uint256 minAmountOutAfterSwap,
        bytes calldata swapData
    ) external onlyRelativePositionManager {
        emit ExitLeverageForwarded(
            address(collateralMarket),
            address(borrowedMarket),
            collateralAmountToRedeemForSwap,
            borrowedAmountToFlashLoan
        );
        ILeverageStrategiesManager(LEVERAGE_MANAGER).exitLeverage(
            collateralMarket,
            collateralAmountToRedeemForSwap,
            borrowedMarket,
            borrowedAmountToFlashLoan,
            minAmountOutAfterSwap,
            swapData
        );
    }

    /**
     * @notice Forwards exitSingleAssetLeverage to the LeverageStrategiesManager on behalf of this position account
     * @dev Only callable by the RelativePositionManager. Use when collateral and debt are the same asset (e.g. DSA == short).
     * @param collateralMarket vToken market for both collateral and debt
     * @param collateralAmountToFlashLoan Amount to borrow via flash loan for debt repayment
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     */
    function exitSingleAssetLeverage(
        IVToken collateralMarket,
        uint256 collateralAmountToFlashLoan
    ) external onlyRelativePositionManager {
        emit ExitSingleAssetLeverageForwarded(address(collateralMarket), collateralAmountToFlashLoan);
        ILeverageStrategiesManager(LEVERAGE_MANAGER).exitSingleAssetLeverage(
            collateralMarket,
            collateralAmountToFlashLoan
        );
    }

    /**
     * @notice Exits a market by calling comptroller.exitMarket with this position account as the sender
     * @dev Only callable by the RelativePositionManager. The position account directly calls the Comptroller.
     * @param vTokenToExit Address of the vToken market to exit
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     * @custom:error ExitMarketFailed if the exit market operation fails.
     */
    function exitMarket(address vTokenToExit) external onlyRelativePositionManager {
        uint256 err = COMPTROLLER.exitMarket(vTokenToExit);
        if (err != 0) revert ExitMarketFailed(err);
        emit MarketExited(vTokenToExit);
    }

    /**
     * @notice Transfers full balance of an ERC20 token from this position account to its owner (dust recovery)
     * @dev Only callable by the RelativePositionManager. Used to sweep dust to the position owner.
     * @param token Address of the ERC20 token to transfer
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     */
    function transferDustToOwner(address token) external onlyRelativePositionManager {
        uint256 balance = IERC20Upgradeable(token).balanceOf(address(this));
        if (balance > 0) {
            IERC20Upgradeable(token).safeTransfer(owner, balance);
            emit DustTransferredToOwner(token, owner, balance);
        }
    }

    /**
     * @notice Executes multiple generic calls to external contracts
     * @dev Only callable by the authorized RelativePositionManager contract.
     *      Uses AddressUpgradeable.functionCall for safer execution and reverts on failure.
     * @param targets Array of target contract addresses
     * @param data Array of encoded function call data
     * @custom:error UnauthorizedCaller if caller is not the RelativePositionManager.
     * @custom:error InvalidCallsLength if arrays are empty or lengths mismatch.
     */
    function genericCalls(address[] calldata targets, bytes[] calldata data) external onlyRelativePositionManager {
        uint256 length = targets.length;
        if (length == 0 || length != data.length) {
            revert InvalidCallsLength();
        }

        for (uint256 i = 0; i < length; ++i) {
            targets[i].functionCall(data[i]);
            emit GenericCallExecuted(targets[i], data[i]);
        }
    }
}

